use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl ProjectBuilder { # [doc = " Root of the project"] # [doc = ""] # [doc = " ex: `$CARGO_TARGET_TMPDIR/cit/t0/foo`"] pub fn root (& self) -> PathBuf { self . root . root () } # [doc = " Project's debug dir"] # [doc = ""] # [doc = " ex: `$CARGO_TARGET_TMPDIR/cit/t0/foo/target/debug`"] pub fn target_debug_dir (& self) -> PathBuf { self . root . target_debug_dir () } # [doc = " Create project in `root`"] pub fn new (root : PathBuf) -> ProjectBuilder { ProjectBuilder { root : Project { root } , files : vec ! [] , symlinks : vec ! [] , no_manifest : false , } } # [doc = " Create project, relative to [`paths::root`]"] pub fn at < P : AsRef < Path > > (mut self , path : P) -> Self { self . root = Project { root : paths :: root () . join (path) , } ; self } # [doc = " Adds a file to the project."] pub fn file < B : AsRef < Path > > (mut self , path : B , body : & str) -> Self { self . _file (path . as_ref () , body , false) ; self } # [doc = " Adds an executable file to the project."] pub fn executable < B : AsRef < Path > > (mut self , path : B , body : & str) -> Self { self . _file (path . as_ref () , body , true) ; self } fn _file (& mut self , path : & Path , body : & str , executable : bool) { self . files . push (FileBuilder :: new (self . root . root () . join (path) , body , executable ,)) ; } # [doc = " Adds a symlink to a file to the project."] pub fn symlink (mut self , dst : impl AsRef < Path > , src : impl AsRef < Path >) -> Self { self . symlinks . push (SymlinkBuilder :: new (self . root . root () . join (dst) , self . root . root () . join (src) ,)) ; self } # [doc = " Create a symlink to a directory"] pub fn symlink_dir (mut self , dst : impl AsRef < Path > , src : impl AsRef < Path >) -> Self { self . symlinks . push (SymlinkBuilder :: new_dir (self . root . root () . join (dst) , self . root . root () . join (src) ,)) ; self } pub fn no_manifest (mut self) -> Self { self . no_manifest = true ; self } # [doc = " Creates the project."] pub fn build (mut self) -> Project { self . rm_root () ; self . root . root () . mkdir_p () ; let manifest_path = self . root . root () . join ("Cargo.toml") ; if ! self . no_manifest && self . files . iter () . all (| fb | fb . path != manifest_path) { self . _file (Path :: new ("Cargo.toml") , & basic_manifest ("foo" , "0.0.1") , false ,) } let past = time :: SystemTime :: now () - Duration :: new (1 , 0) ; let ftime = filetime :: FileTime :: from_system_time (past) ; for file in self . files . iter_mut () { file . mk () ; if is_coarse_mtime () { filetime :: set_file_times (& file . path , ftime , ftime) . unwrap () ; } } for symlink in self . symlinks . iter_mut () { symlink . mk () ; } let ProjectBuilder { root , .. } = self ; root } fn rm_root (& self) { self . root . root () . rm_rf () } }
}